/**
 * Picks one value from a few options that are all visible (`design/components/radio.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/radio.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import * as zag from '@zag-js/radio-group'

import {
  MEMBER_PROVIDERS,
  Ref,
  agentMember,
  derived,
  elementRef,
  fieldValue,
  mountEffect,
  normalizeProps,
  presence,
  roveRadio,
  setup,
  uniqueId,
  useDirection,
  useMachine,
  useMember,
  type Each,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/controls/radio-group.module.css'

export type RadioOrientation = NonNullable<RadioGroupProps['orientation']>

export interface RadioOption {
  value: string
  label: string
  disabled?: boolean
}

/** Picks one value from a few options that are all visible: the inputs it takes, by the React member's prop names. */
export interface RadioGroupProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField, because the group's question is the field's label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  defaultValue?: string
  disabled?: boolean
  id?: string
  invalid?: boolean
  name?: string
  options: RadioOption[]
  /**
   * Horizontal is for three short labels at most. Guidance, not enforcement.
   */
  orientation?: 'horizontal' | 'vertical'
  value?: string
}

/** Picks one value from a few options that are all visible. */
@Component({
  selector: 'pm-radio-group',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref],
  // prettier-ignore
  template: `<!-- root -->
<div
[attr.class]="e1()"
role="radiogroup"
[attr.id]="e2()"
[attr.aria-label]="e3()"
[attr.aria-labelledby]="e4()"
[attr.aria-describedby]="e5()"
[attr.aria-required]="e6()"
[attr.aria-invalid]="e7()"
[attr.data-orientation]="e8()"
[attr.data-disabled]="e9()"
[attr.data-invalid]="e10()"
[attr.data-required]="e11()"
data-member="radio-group"
[pmRef]="group"
>@for (option of e12(); track e13(option)) {<!-- row -->
<label
[attr.class]="e14()"
><!-- radio -->
<button
[attr.class]="e15()"
type="button"
role="radio"
[attr.value]="e13(option)"
[attr.aria-checked]="e16(option)"
[attr.disabled]="e17(option)"
[attr.tabindex]="e18(option)"
[attr.data-state]="e19(option)"
[attr.data-disabled]="e20(option)"
(click)="h1(option)"
(keydown)="h2($event)"
>@if (e16(option)) {<!-- dot -->
<span
[attr.class]="e21(option)"
data-state="checked"
></span>}</button>
<span
[attr.class]="e22()"
>{{ e23(option) }}</span></label>}</div>
@if (e24()) {<input
type="hidden"
[attr.name]="e25()"
[value]="e26()"
[attr.disabled]="e27()"
/>}`,
})
export class RadioGroup {
  static readonly controlKind = 'group'
  readonly ariaDescribedby = input<RadioGroupProps['aria-describedby']>(undefined, {
    alias: 'aria-describedby',
  })
  /**
   * Wired by FormField, because the group's question is the field's label.
   */
  readonly ariaLabel = input<RadioGroupProps['aria-label']>(undefined, { alias: 'aria-label' })
  readonly ariaLabelledby = input<RadioGroupProps['aria-labelledby']>(undefined, {
    alias: 'aria-labelledby',
  })
  readonly ariaRequired = input<RadioGroupProps['aria-required']>(undefined, {
    alias: 'aria-required',
  })
  readonly defaultValue = input<RadioGroupProps['defaultValue']>(undefined)
  readonly disabled = input<
    Exclude<RadioGroupProps['disabled'], undefined>,
    RadioGroupProps['disabled']
  >(false, {
    transform: (value: RadioGroupProps['disabled']) => (value === undefined ? false : value),
  })
  readonly id = input<RadioGroupProps['id']>(undefined)
  readonly invalid = input<
    Exclude<RadioGroupProps['invalid'], undefined>,
    RadioGroupProps['invalid']
  >(false, {
    transform: (value: RadioGroupProps['invalid']) => (value === undefined ? false : value),
  })
  readonly name = input<RadioGroupProps['name']>(undefined)
  readonly options = input.required<RadioGroupProps['options']>()
  /**
   * Horizontal is for three short labels at most. Guidance, not enforcement.
   */
  readonly orientation = input<
    Exclude<RadioGroupProps['orientation'], undefined>,
    RadioGroupProps['orientation']
  >('vertical', {
    transform: (value: RadioGroupProps['orientation']) =>
      value === undefined ? 'vertical' : value,
  })
  readonly value = input<RadioGroupProps['value']>(undefined)
  readonly onChange = output<string>({ alias: 'change' })
  protected readonly $ = useMember({
    kind: RadioGroup.controlKind,
    events: ['change'],
    props: {
      'aria-describedby': () => this.ariaDescribedby(),
      'aria-label': () => this.ariaLabel(),
      'aria-labelledby': () => this.ariaLabelledby(),
      'aria-required': () => this.ariaRequired(),
      defaultValue: () => this.defaultValue(),
      disabled: () => this.disabled(),
      id: () => this.id(),
      invalid: () => this.invalid(),
      name: () => this.name(),
      options: () => this.options(),
      orientation: () => this.orientation(),
      value: () => this.value(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly uid = uniqueId()
  protected readonly group = elementRef<HTMLElement>()
  protected readonly documentDirection = useDirection()
  protected readonly service: { readonly value: zag.Service } = setup(() =>
    useMachine(
      zag.machine,
      () =>
        ({
          id: this.uid,
          dir: this.documentDirection(),
          value: this.$p.value,
          defaultValue: this.$p.defaultValue,
          disabled: this.$p.disabled,
          name: this.$p.name,
          orientation: this.$p.orientation,
          onValueChange: (details) => {
            this.$.emit(this.onChange, 'onChange', details.value ?? '')
          },
        }) as Partial<zag.Props>,
    ),
  )
  protected readonly api: { readonly value: ReturnType<typeof zag.connect> } = derived(() =>
    zag.connect(this.service.value, normalizeProps),
  )
  protected readonly stop = derived(
    () =>
      this.api.value.value ??
      this.$p.options.find((option) => !(this.$p.disabled || option.disabled === true))?.value,
  )
  private release1: (() => void) | undefined

  constructor() {
    inject(DestroyRef).onDestroy(() => this.release1?.())
    mountEffect(() => this.effect1())
  }

  protected e1() {
    return styles.group
  }

  protected e2() {
    return this.$p.id
  }

  protected e3() {
    return this.$p['aria-label']
  }

  protected e4() {
    return this.$p['aria-labelledby']
  }

  protected e5() {
    return this.$p['aria-describedby']
  }

  protected e6() {
    return this.$p['aria-required']
  }

  protected e7() {
    return this.$p.invalid ? true : undefined
  }

  protected e8() {
    return this.$p.orientation
  }

  protected e9() {
    return this.$p.disabled ? '' : undefined
  }

  protected e10() {
    return this.$p.invalid ? '' : undefined
  }

  protected e11() {
    return this.$p['aria-required'] ? '' : undefined
  }

  e12() {
    return this.$p.options
  }

  protected e13(option: Each<ReturnType<RadioGroup['e12']>>) {
    return option.value
  }

  protected e14() {
    return styles.row
  }

  protected e15() {
    return styles.circle
  }

  protected e16(option: Each<ReturnType<RadioGroup['e12']>>) {
    return this.api.value.value === option.value
  }

  protected e17(option: Each<ReturnType<RadioGroup['e12']>>) {
    return presence(this.$p.disabled || option.disabled === true)
  }

  protected e18(option: Each<ReturnType<RadioGroup['e12']>>) {
    return option.value === this.stop.value ? 0 : -1
  }

  protected e19(option: Each<ReturnType<RadioGroup['e12']>>) {
    return this.api.value.value === option.value ? 'checked' : 'unchecked'
  }

  protected e20(option: Each<ReturnType<RadioGroup['e12']>>) {
    return this.$p.disabled || option.disabled === true ? '' : undefined
  }

  protected h1(option: Each<ReturnType<RadioGroup['e12']>>): void {
    this.api.value.setValue(option.value)
  }

  protected h2($event: KeyboardEvent): void {
    void ($event.key === 'Enter'
      ? $event.preventDefault()
      : roveRadio($event, (next) => this.api.value.setValue(next)))
  }

  protected e21(option: Each<ReturnType<RadioGroup['e12']>>) {
    if (!(this.api.value.value === option.value)) return undefined as never
    return styles.dot
  }

  protected e22() {
    return styles.label
  }

  protected e23(option: Each<ReturnType<RadioGroup['e12']>>) {
    return option.label
  }

  protected e24() {
    return this.$p.name !== undefined
  }

  protected e25() {
    if (!(this.$p.name !== undefined)) return undefined as never
    return this.$p.name
  }

  protected e26() {
    if (!(this.$p.name !== undefined)) return undefined as never
    return fieldValue(this.api.value.value ?? '')
  }

  protected e27() {
    if (!(this.$p.name !== undefined)) return undefined as never
    return presence(this.$p.disabled)
  }

  private effect1(): void {
    this.release1?.()
    const ran = agentMember({
      member: 'RadioGroup',
      element: () => this.group.value,
      state: () => ({
        value: this.api.value.value ?? null,
        options: this.$p.options.map((option) => ({
          id: option.value,
          label: option.label,
          ...(option.disabled === true ? { disabled: true } : {}),
        })),
        disabled: this.$p.disabled,
        invalid: this.$p.invalid,
      }),
      actions: {
        choose: {
          argument: 'id',
          run: (value) => value !== this.api.value.value && this.api.value.setValue(value),
        },
      },
    })
    this.release1 = () => {
      ran()
    }
  }
}
